import re

lines = open('/tmp/<path>').read().splitlines()
prog = []
for ln in lines:
    ln = ln.split(';')[0].strip()
    if ln:
        prog.append(ln.split())

regs = {'a':0,'b':0,'c':0,'d':0}
M = 65536

def val(x):
    x = x.strip()
    if x in regs:
        return regs[x]
    return int(x)

outs = []
count = 0
pc = 0
steps = 0
while 0 <= pc < len(prog):
    ins = prog[pc]
    op = ins[0]
    steps += 1
    if steps > 10**7:
        print("TOO MANY"); break
    count += 1
    if op == 'set':
        regs[ins[1]] = val(ins[2]) % M
    elif op == 'add':
        regs[ins[1]] = (regs[ins[1]] + val(ins[2])) % M
    elif op == 'mul':
        regs[ins[1]] = (regs[ins[1]] * val(ins[2])) % M
    elif op == 'mod':
        x = val(ins[2])
        if x > 0:
            regs[ins[1]] = regs[ins[1]] % x
    elif op == 'dec':
        regs[ins[1]] = max(0, regs[ins[1]] - 1)
    elif op == 'jnz':
        if val(ins[1]) != 0:
            pc += val(ins[2])
            continue
    elif op == 'skp':
        if val(ins[1]) < val(ins[2]):
            pc += 2
            continue
    elif op == 'out':
        outs.append(val(ins[1]))
    else:
        raise Exception(op)
    pc += 1

print("outs:", outs)
print("sum:", sum(outs))
print("count:", count)
print("len outs:", len(outs))

